contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test: deposit some amount, call withdrawAll once, then call withdrawAll a second time;
    // assert that if the first withdrawAll succeeded then the second withdrawAll leaves both balances unchanged
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // perform a deposit into c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // record balances before first withdraw
        uint cBal_beforeFirst = address(c).balance;
        uint myBal_beforeFirst = address(this).balance;

        bool firstReverted;
        // first withdrawAll call (must be a top-level statement)
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // record balances after first withdraw and before second
        uint cBal_beforeSecond = address(c).balance;
        uint myBal_beforeSecond = address(this).balance;

        bool secondReverted;
        // second withdrawAll call (must be a top-level statement)
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // record balances after second
        uint cBal_afterSecond = address(c).balance;
        uint myBal_afterSecond = address(this).balance;

        // Single assert expressing the general rule:
        // If the first withdrawAll succeeded then the second withdrawAll must not transfer any additional Ether,
        // i.e., c's balance and this contract's balance remain equal to their values immediately before the second call.
        // If the first reverted, we do not require anything specific (the assertion allows any outcome in that case).
        assert(firstReverted || (cBal_afterSecond == cBal_beforeSecond && myBal_afterSecond == myBal_beforeSecond));
    }

    receive() external payable { }
}

